import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`subscription-tracking`,heroTitle:`Track your subscriptions in minutes`,heroSubtitle:`Perplexity Computer finds every subscription, spots double charges, and flags overpayments automatically.`,inputUrlPrefill:`Connect my accounts via Plaid and audit for all active subscriptions and recurring charges. Identify: 1) Every recurring payment with amount, billing cycle, and next charge date. 2) Duplicate or overlapping subscriptions where I’m double paying for similar services. 3) Subscriptions that have increased in price since I signed up. 4) Services I haven’t used recently that I could cancel. 5) Cheaper alternatives or available discounts for my current plans. Deliver a full subscription audit with total monthly and annual spend, a prioritized list of savings opportunities, and step-by-step cancellation instructions for each recommendation.`,heroOverlaySteps:[`Scanning your account for every recurring charge and subscription`,`Cross-referencing services to detect duplicate and overlapping payments`,`Calculating total spend and identifying price increases across all subscriptions`,`Savings opportunities, cancellation steps, and cheaper alternatives — ready to act on`],featureSectionTitle:`From statements to savings`,featureCardTitles:[`Connects to your financial stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Bank accounts, credit cards, Google Sheets, Notion — Computer plugs into your tools so subscription tracking, alerts, and savings happen in one workflow.`,`Full subscription inventory. Duplicate payment alerts. Annual spend breakdown. Cancellation instructions. Cheaper alternative recommendations.`],capabilitySectionTitle:`Your financial watchdog, on autopilot`,capabilitySectionSubtitle:`Connect your accounts, step away, come back to a complete savings plan.`,capabilityCards:[{title:`Subscription Discovery`,description:`Computer can scan your transactions and surface every recurring charge — even ones buried in annual billing cycles or under unfamiliar merchant names.`},{title:`Duplicate Detection`,description:`Computer can cross-reference your subscriptions and flag where you’re paying twice for similar services — like two cloud storage plans or overlapping streaming bundles.`},{title:`Savings Recommendations`,description:`Computer can research cheaper alternatives, available discounts, and family plan options — and estimate exactly how much you’d save by switching.`},{title:`Connect Your Tools`,description:`Computer can read from your bank accounts, credit cards, Google Sheets, and more — build workflows across your entire financial stack.`},{title:`Remember & Learn`,description:`Computer can remember your subscriptions, spending patterns, and preferences across sessions — so every audit builds on what came before.`},{title:`Price Watch Alerts`,description:`Computer can monitor your subscriptions for price increases, new charges, and free trial expirations — and ping you before you get billed.`}]});export{t as default};
